//! Ordinary Result records carry native address values and owned DNS snapshots.
use super::*;
impl Emitter<'_>{
 fn net_record(&self,id:usize,fields:Vec<String>)->String{let fields=fields.into_iter().enumerate().map(|(index,value)|format!("field{index}:{value}")).collect::<Vec<_>>().join(",");format!("Record{}{{{fields}{}}}",self.native_record_declaration(id),self.schema_record_order(id))}
 fn net_value(&self,ty:Type,value:&str)->String{match ty{Type::String=>format!("String::Owned({value})"),Type::Record(id) if self.program.records[id].is_tuple()=>{let tuple=self.net_record(id,self.program.records[id].fields.iter().enumerate().map(|(index,field)|self.net_value(field.ty.unwrap(),&format!("net_tuple.{index}"))).collect());format!("{{let net_tuple={value};{tuple}}}")},Type::Record(id) if self.program.records[id].native_type==Some(crate::native_signatures::NativeTypeId::Bytes)=>format!("Record{}{{bytes:{value}}}",self.native_record_declaration(id)),Type::Record(id) if self.program.records[id].native_type==Some(crate::native_signatures::NativeTypeId::Datagram)=>{let fields=&self.program.records[id].fields;self.net_record(id,vec![self.net_value(fields[0].ty.unwrap(),&format!("({value}).data")),format!("({value}).remote")])},Type::Array(element)=>format!("({value}).into_iter().map(|item|{}).collect::<{}>()",self.net_value(element.ty(),"item"),self.native_type(ty)),_=>value.into()}}
 fn net_result(&self,ty:Type,call:&str)->String{let Type::Union(id)=ty else{unreachable!("network Result")};let members=&self.program.unions[id.index()].members;let[ok,err]=crate::result_identity::variants(&self.program.records,members).unwrap();let tag=|record|members.iter().position(|ty|*ty==Type::Record(record)).unwrap();let success=self.net_record(ok,self.program.records[ok].fields.first().map(|field|vec![self.net_value(field.ty.unwrap(),"value")]).unwrap_or_default());let Type::Record(error)=self.program.records[err].fields[0].ty.unwrap()else{unreachable!()};let Type::Union(os)=self.program.records[error].fields[3].ty.unwrap()else{unreachable!()};let present=self.program.unions[os.index()].members.iter().position(|ty|*ty==Type::Int).unwrap();let absent=1-present;let payload=self.net_record(error,vec!["String::Borrowed(error.code)".into(),"String::Borrowed(error.operation)".into(),"String::Owned(error.message)".into(),format!("match error.os_code{{Some(value)=>Union{}::V{present}(value),None=>Union{}::V{absent}(TsrUndefined)}}",os.index(),os.index())]);let failure=self.net_record(err,vec![payload]);format!("match {call}{{Ok(value)=>Union{}::V{}({success}),Err(error)=>Union{}::V{}({failure})}}",id.index(),tag(ok),id.index(),tag(err))}
 pub(super) fn net_forward(&self,fun:&CheckedFunction,parameters:&[usize],span:crate::Span,id:usize)->Option<String>{if crate::native_bindings::BINDINGS[id].module!="std:net"{return None;}let arguments=parameters.iter().map(|&id|{let binding=&fun.bindings[id];let mut value=Expr::new(ExprKind::Name(binding.name.clone()),span);value.binding=Some(id);value.ty=Some(binding.ty);value}).collect::<Vec<_>>();let mut result=Expr::new(ExprKind::Undefined,span);result.ty=Some(fun.result);self.net_native(fun,&result,id,&arguments)}
 pub(super) fn net_native(&self,fun:&CheckedFunction,expr:&Expr,id:usize,args:&[Expr])->Option<String>{let binding=&crate::native_bindings::BINDINGS[id];if !matches!(binding.module,"std:net"|"std:dns"){return None;}self.native_bindings.borrow_mut().insert(id);let values=args.iter().zip(binding.parameters).map(|(argument,parameter)|if parameter.ty.signature()==crate::native_signatures::Signature::String{self.string_observation(fun,argument)}else{self.expr(fun,argument,parameter.access)}).collect::<Vec<_>>();let call=if binding.module=="std:dns"{let family=if let Some(argument)=args.get(1){let optional=self.native_optional_argument(&binding.parameters[1],values[1].clone(),argument.ty.unwrap());format!("({optional}).map(|value|match value.as_ref(){{\"any\"=>tsrust_native_dns::Family::Any,\"ipv4\"=>tsrust_native_dns::Family::Ipv4,\"ipv6\"=>tsrust_native_dns::Family::Ipv6,_=>unreachable!(\"checked DNS family\")}}).unwrap_or_default()")}else{"tsrust_native_dns::Family::Any".into()};format!("tsrust_native_dns::lookup({},{}).await",values[0],family)}else if matches!(binding.name,"__listenTcp"|"__connectTcp"|"__bindUdp"){format!("tsrust_native_net_transport::{}({}).await",match binding.name{"__listenTcp"=>"listen","__connectTcp"=>"connect",_=>"bind_udp"},values[0])}else if binding.name.starts_with("__"){let method=match binding.name{"__accept"=>"accept","__listenerAddress"|"__streamLocal"|"__udpAddress"=>"local_address","__streamPeer"=>"peer_address","__setNoDelay"=>"set_no_delay","__shutdownWrite"=>"shutdown_write","__split"=>"split","__sendTo"=>"send_to","__receiveFrom"=>"receive_from","__listenerClose"|"__streamClose"|"__udpClose"=>"close",_=>unreachable!()};let arguments=values.iter().enumerate().skip(1).map(|(index,value)|if binding.name=="__sendTo"&&index==1{format!("({value}).readable_bytes()")}else{value.clone()}).collect::<Vec<_>>().join(",");format!("({}).{method}({arguments}){}",values[0],if matches!(binding.name,"__accept"|"__shutdownWrite"|"__sendTo"|"__receiveFrom"){".await"}else{""})}else{let name=match binding.name{"parseIp"=>"parse_ip","formatIp"=>"format_ip","parseAddress"=>"parse_address","formatAddress"=>"format_address","isIPv4"=>"is_ipv4","isIPv6"=>"is_ipv6",_=>unreachable!()};format!("tsrust_native_net::{name}({})",values[0])};Some(if matches!(binding.result,crate::native_bindings::NativeType::Structured(crate::native_signatures::Signature::Result(..))){self.net_result(expr.ty.unwrap(),&call)}else{self.net_value(expr.ty.unwrap(),&call)})}
}
